import * as React from "react";
import { cx } from "./cx";

export interface AvatarProps extends React.HTMLAttributes<HTMLSpanElement> {
  src?: string;
  alt?: string;
  /** Shown when there is no image, or when it fails to load. */
  initials?: string;
  size?: "sm" | "md" | "lg";
}

export function Avatar({ src, alt, initials, size = "md", className, ...props }: AvatarProps) {
  const [failed, setFailed] = React.useState(false);
  const showImage = src && !failed;
  return (
    <span
      className={cx("rs-avatar", size === "sm" && "rs-avatar-sm", size === "lg" && "rs-avatar-lg", className)}
      {...props}
    >
      {showImage ? <img src={src} alt={alt ?? ""} onError={() => setFailed(true)} /> : initials}
    </span>
  );
}

/** Overlapping row with paper seams. */
export function AvatarRow({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cx("rs-avatar-row", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Avatar: initials in a quiet circle; images cover ── */
.rs-avatar{width:32px;height:32px;border-radius:50%;background:var(--divider-subtle);color:var(--text);display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:600;letter-spacing:-.01em;overflow:hidden;flex-shrink:0;user-select:none}
.rs-avatar img{width:100%;height:100%;object-fit:cover}
.rs-avatar-sm{width:24px;height:24px;font-size:10px}
.rs-avatar-lg{width:48px;height:48px;font-size:16px}
.rs-avatar-row{display:flex}
.rs-avatar-row .rs-avatar{border:2px solid var(--bg);margin-left:-8px}
.rs-avatar-row .rs-avatar:first-child{margin-left:0}
